/* ---------- 0.4.0: wider shelves, seed catalogue & journal ---------- */
.modal{max-height:min(90vh,820px);overflow:auto;scrollbar-width:thin}
.modal.wide{width:min(900px,100%)}
.modal-body{margin-top:14px}
.modal-options{max-height:52vh;overflow:auto;padding-right:3px}
.modal-options::-webkit-scrollbar,.dvd-grid::-webkit-scrollbar,.seed-grid::-webkit-scrollbar{width:7px}
.modal-options::-webkit-scrollbar-thumb,.dvd-grid::-webkit-scrollbar-thumb,.seed-grid::-webkit-scrollbar-thumb{background:#d3dcc6;border-radius:5px}
.modal-note{margin-top:11px;font-size:10px;line-height:1.45;color:#8d9888;background:#f4f3e7;border-radius:6px;padding:9px 11px}
.shelf-tabs,.seed-tabs{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-top:14px}
.shelf-tabs button,.seed-tabs button{border:1px solid #e4e7d9;background:#fffef8;color:#76846f;font:9px var(--pixel);border-radius:999px;padding:7px 11px;cursor:pointer;transition:.15s}
.shelf-tabs button:hover,.seed-tabs button:hover{background:#eff2e6}
.shelf-tabs button.active,.seed-tabs button.active{background:#5c7a62;border-color:#5c7a62;color:#fffaf0}
.seed-status{margin-left:auto;font:9px var(--pixel);color:#a0a795;white-space:nowrap}
.dvd-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(165px,1fr));gap:8px;max-height:47vh;overflow:auto;margin-top:12px;padding:1px 4px 3px 1px}
.dvd-card{display:flex;gap:9px;align-items:center;border:1px solid #e8e9dd;background:#fffefb;border-radius:8px;padding:7px;text-align:left;color:var(--ink);cursor:pointer;transition:.15s;position:relative;overflow:hidden}
.dvd-card:hover{background:#f3f5ea;border-color:#cfdbc2;transform:translateY(-1px)}
.dvd-art{width:47px;height:58px;flex:none;border-radius:4px;background:linear-gradient(145deg,var(--a),var(--b));display:grid;place-items:center;position:relative;box-shadow:inset -5px 0 #00000018,0 1px 2px #00000018}
.dvd-art b{font-size:21px;filter:drop-shadow(0 1px 1px #0004)}
.dvd-art i{position:absolute;bottom:3px;right:5px;font:6px var(--pixel);font-style:normal;color:#fffdf0cc}
.dvd-copy{min-width:0}
.dvd-copy b{font-size:10px;line-height:1.2;display:block}
.dvd-copy small{display:block;font-size:8px;line-height:1.35;color:#949d8e;margin-top:3px}
.dvd-card.watched::after{content:'✓';position:absolute;right:6px;top:5px;font-size:9px;color:#fff;background:#7d9773;border-radius:50%;width:14px;height:14px;display:grid;place-items:center}
.seed-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(156px,1fr));gap:8px;max-height:48vh;overflow:auto;margin-top:12px;padding:1px 4px 3px 1px}
.seed-card{display:flex;gap:9px;align-items:flex-start;border:1px solid #e8e9dd;background:#fffefb;border-radius:8px;padding:8px;text-align:left;color:var(--ink);cursor:pointer;transition:.15s;position:relative}
.seed-card:hover{background:#f3f5ea;border-color:#cfdbc2;transform:translateY(-1px)}
.seed-card:disabled{opacity:.5;cursor:default;transform:none}
.seed-art{width:40px;height:43px;flex:none;border-radius:6px;background:linear-gradient(160deg,var(--leaf2),var(--leaf));position:relative;display:grid;place-items:center;overflow:hidden}
.seed-art b{font-size:19px;z-index:2;filter:drop-shadow(0 1px 1px #0004)}
.seed-art i{position:absolute;width:16px;height:6px;border-radius:50%;background:var(--accent);opacity:.75}
.seed-art i:nth-child(2){left:-3px;bottom:4px;transform:rotate(-25deg)}
.seed-art i:nth-child(3){right:-2px;bottom:9px;transform:rotate(18deg)}
.seed-art i:nth-child(4){right:5px;top:3px;width:8px;height:8px}
.seed-copy{min-width:0;flex:1}
.seed-copy b{font-size:10px;display:block}
.seed-copy small{display:block;font-size:8px;color:#78906d;letter-spacing:.2px;margin-top:2px;font-family:var(--pixel)}
.seed-copy em{display:block;font-size:8px;line-height:1.3;color:#9aa391;font-style:normal;margin-top:3px}
.seed-price{position:absolute;right:7px;bottom:6px;font:7px var(--pixel);color:#b08a54}
.harvest-list{display:grid;gap:6px;margin-bottom:14px;max-height:43vh;overflow:auto}
.harvest-row{display:flex;align-items:center;gap:9px;background:#f7f6ea;border:1px solid #ececdf;border-radius:7px;padding:8px 10px}
.harvest-row span{font-size:17px}
.harvest-row b{font-size:11px;flex:1}
.harvest-row small{font:8px var(--pixel);color:#92a087}
.harvest-list+.ritual-button{width:100%}
.journal-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}
.journal-card{background:#f3f4e8;border:1px solid #e9ebdd;border-radius:8px;padding:10px 11px}
.journal-card span{font:8px var(--pixel);letter-spacing:.7px;color:#a0a795;display:block}
.journal-card b{font-size:21px;display:block;margin-top:2px;color:#536b58}
.journal-card small{font-size:9px;color:#929d8c;display:block;margin-top:2px;line-height:1.3}
.journal-lists{display:grid;grid-template-columns:1fr 1fr;gap:9px 16px;margin-top:14px}
